// Idempotence : verifie qu'on n'a pas deja traite cette commande
// (un webhook peut etre renvoye plusieurs fois par le backend en cas de retry)
const body = $input.first().json.body;
const orderId = body.orderId || body.id;

if (!orderId) {
  return [{ json: { error: true, message: 'orderId manquant dans le payload' } }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedOrderIds) staticData.processedOrderIds = [];

if (staticData.processedOrderIds.includes(orderId)) {
  return [{ json: { error: true, message: 'Commande deja traitee (doublon webhook)', orderId, skip: true } }];
}

// Garder seulement les 500 derniers ids pour ne pas faire grossir staticData indefiniment
staticData.processedOrderIds.push(orderId);
if (staticData.processedOrderIds.length > 500) {
  staticData.processedOrderIds = staticData.processedOrderIds.slice(-500);
}

return [{
  json: {
    error: false,
    orderId,
    orderNumber: body.orderNumber || orderId,
    customerWhatsapp: body.customer?.whatsappNumber || body.customerWhatsapp,
    deliveryZoneId: body.deliveryZoneId,
    deliveryAddress: body.deliveryAddress,
    items: body.items || [],
    total: body.total
  }
}];

// Si aucun commercial n'est associe a la zone, on tombe sur une rotation par defaut
// ou sur un commercial "general" pour ne jamais perdre une commande sans suivi.
const response = $input.first().json;
const order = $('Verifier doublon (idempotence)').first().json;

let salesReps = response.body || response;
if (!Array.isArray(salesReps) || salesReps.length === 0) {
  // Fallback : pas de commercial assigne a cette zone -> on alerte un canal general
  salesReps = [{ id: null, name: 'Equipe commerciale (non assignee)', whatsappNumber: $env.SALES_FALLBACK_WHATSAPP_NUMBER }];
}

return salesReps.map(rep => ({
  json: {
    ...order,
    salesRepId: rep.id,
    salesRepName: rep.name,
    salesRepWhatsapp: rep.whatsappNumber
  }
}));

// Construit le texte recapitulatif de la commande pour le commercial
const rep = $('Preparer liste commerciaux a notifier').first().json;

const itemsText = (rep.items || []).map(i => `- ${i.quantity} x ${i.productName || i.productId}`).join('\n');

const text = `Nouvelle commande CCB !\n\n` +
  `Commande : ${rep.orderNumber}\n` +
  `Client : ${rep.customerWhatsapp}\n` +
  `Adresse : ${rep.deliveryAddress || 'non precisee'}\n\n` +
  `Articles :\n${itemsText}\n\n` +
  (rep.total ? `Total : ${rep.total} FCFA\n\n` : '') +
  `Voir la fiche : ${$env.ADMIN_BASE_URL}/admin/orders/${rep.orderId}`;

return [{
  json: {
    messaging_product: 'whatsapp',
    to: rep.salesRepWhatsapp,
    type: 'text',
    text: { body: text }
  }
}];
